INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-002', 'AB Communication / Mass Communication / Journalism', 'Other', 'INTERNATIONAL', 'Moderate', ARRAY['Singapore', 'UAE', 'UK', 'USA', 'Hong Kong'], FALSE, NULL, 4, 'Build a portfolio from day one — published articles, PR campaigns you''ve run, content you''ve produced, analytics results. No employer abroad cares about your GPA; they care about your work. The fastest international pathway is remote content/digital marketing — build skills in SEO (take Google''s free courses), content strategy, and social media analytics. Within 2 years you can be earning $30,000-50,000/year remotely from the Philippines before even moving. For journalism: file clips with national newspapers, wire services, and international outlets covering Philippine stories — this is your portfolio.', 'Communication/journalism graduates have one of the more diverse international career landscapes among social science graduates because skills are portable. Key pathways: (1) INTERNATIONAL JOURNALISM: Filipino journalists have worked at Reuters (Manila bureau and international postings), AFP, AP, Bloomberg, CNN Philippines affiliates. Wire service stringer/contributor work begins locally but international postings are competitive. Al Jazeera English in Doha actively diversifies its newsroom. BBC World Service Southeast Asia bureau covers Philippines. For broadcast, CNN (Atlanta or international bureaus) requires strong on-camera reel + digital skills. Starting international journalism salary: $28,000-45,000 at wire agencies; senior international correspondent: $70,000-100,000. (2) PR / COMMUNICATIONS IN MNC HUB CITIES: Singapore, Hong Kong, Dubai, and Kuala Lumpur are regional hubs for multinational PR agencies (Edelman, Ogilvy PR, Weber Shandwick, FleishmanHillard, Burson Marsteller). Filipino communications professionals are valued for English fluency, ASEAN market knowledge, and strong work ethic. Agency roles: $30,000-60,000 (SGD/HKD/AED equivalents). In-house comms at MNCs: $40,000-80,000. (3) CONTENT MARKETING / DIGITAL (REMOTE): The fastest-growing international pathway. Filipino content marketers, copywriters, SEO specialists, and social media managers now command $25,000-60,000/year working remotely for US, UK, and Australian clients. Platforms: Upwork, Toptal, LinkedIn. Key skills: SEO writing, content strategy, HubSpot/Salesforce marketing, social media analytics. (4) SOCIAL MEDIA / INFLUENCER MANAGEMENT: Digital agencies in Singapore, Dubai, and Bangkok hire Filipino social media strategists. (5) BROADCAST MEDIA in Gulf: Abu Dhabi Media, Qatar Al Jazeera, Saudi MBC have Filipino on-air talent (particularly in technical/production roles and for Filipino community programming).')
