INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-004', 'AB/BS Economics', 'Business & Management', 'SELECTIVE', 'Moderate-High', ARRAY['Philippines (ADB/Manila)', 'USA', 'UK', 'Singapore', 'multilateral institutions globally'], FALSE, NULL, 4, 'For the premium multilateral track (ADB/World Bank/IMF): pursue a Masters or PhD in Economics, preferably from a top US or UK university. ADB YPP is actually ideal for Filipinos — headquarters is in Manila so you get international salary while living in the Philippines. For finance track: take CFA Level 1 concurrently with or after graduation. For development track: UNDP and NGO junior analyst roles are accessible with just a bachelor''s degree and 1-2 years of relevant experience.', 'Economics is the most academically demanding of the 6 courses in this cluster for international premium roles. ADB YPP salary starts ~USD 70,000-90,000 + tax-exempt in Philippines context. World Bank entry roles ~USD 95,000-170,000 mid-level. IMF economist entry (PhD hire) >USD 120,000. However, undergraduate economics graduates without Masters can still find strong roles: financial analyst tracks in Singapore/Australia, policy analyst roles in government ministries, development sector NGOs. Median starting salary for economics majors in USA ~USD 74,000. Singapore financial analyst entry SGD 45,000-60,000/yr. Development NGO entry USD 35,000-55,000.')
