INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-015', 'AB/BS Elementary Education (BEED)', 'Teacher Education', 'INTERNATIONAL', 'High', ARRAY['UK', 'New Zealand', 'Australia', 'UAE', 'Canada'], TRUE, 'Licensure Exam for Teachers (LET) - Elementary', 4, 'Your single biggest advantage over BSED graduates is New Zealand''s Green List — primary teachers can apply for permanent residence directly without first getting a work visa. This is extremely rare in immigration. For UK: apply through Teach Away or directly to MAT (Multi-Academy Trust) groups that sponsor Skilled Worker visas. UAE is your fastest start — many BEED holders are in UAE within 5-8 months of graduating and passing LET.', 'Elementary/Primary teaching (BEED) has excellent international demand — arguably more stable than secondary because every child starts at primary level regardless of economic conditions. The UK, Australia, New Zealand, and Canada all have declared shortages of primary school teachers. New Zealand is particularly significant: primary teachers are on the NZ Green List (Straight to Residence pathway) meaning BEED holders can apply for permanent residence directly — this is a major immigration advantage unique to this profession. The previous research note focused on Secondary (BSED); the BEED pathway to primary/elementary teaching internationally is equally strong and in some countries stronger. UAE is the fastest entry point — no complex credentialing required to start. UK via iQTS or overseas trained teacher route offers the best long-term career and immigration outcome in Europe.')
