INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-001', 'AB/BS Political Science', 'Other', 'DOMESTIC', 'Low', ARRAY['Philippines', 'USA', 'Singapore', 'UK', 'Belgium'], FALSE, NULL, 4, 'Political Science is a gateway degree, not a destination career. The most internationally deployable combination: polisci degree + master''s in public policy (or IR, or journalism) + a specific regional expertise (Southeast Asia, East Asia, South China Sea) + one additional language. For the UN track, target the Young Professionals Programme or Junior Professional Officer program with DFA sponsorship. For the private sector, political risk consulting firms in Singapore or London value ASEAN expertise deeply — your Philippines knowledge is genuinely rare to them.', 'AB/BS Political Science is fundamentally a generalist academic degree. Its primary career outcomes in the Philippines are: government (DFA, DILG, DBM, Congress staff), law school, journalism, or academe. International careers exist but are structurally difficult because: (1) There is no PRC board exam, so there is no internationally recognized credential signal; (2) ''Political scientist'' is rarely a job title outside academia; (3) Employers look for functional skills (policy analysis, research, communications) that polisci teaches but are not exclusive to it. VIABLE INTERNATIONAL PATHWAYS: (A) UN/Multilateral — DFA diplomatic service is domestic, but UN careers in political affairs (DPPA, DPO) require competitive YPP exams, language skills, and a master''s degree. ADB, World Bank, ASEAN Secretariat recruit policy analysts with polisci/IR/economics backgrounds but typically require master''s + quantitative skills. (B) Political Risk Analysis — this is a growing sector. Firms like Control Risks, FTI Consulting, Oxford Analytica, and Verisk Maplecroft hire analysts with regional expertise. Being Filipino and fluent in Southeast Asian political dynamics is a genuine comparative advantage. Starting analyst roles in London/Singapore/New York: $40,000-65,000/year. (C) International Journalism — polisci graduates who develop strong writing skills can pursue journalism with international wire services (Reuters, AFP, Bloomberg, AP) as local correspondents/stringer, or go abroad for graduate study in journalism. (D) Graduate school abroad — the most common international pathway, not a direct career but an enabler.')
