INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('BUS-001', 'BS Accountancy', 'Business & Management', 'INTERNATIONAL', 'High', ARRAY['UAE', 'Singapore', 'Australia'], TRUE, 'Certified Public Accountant Exam (CPALE)', 4, 'Start US CPA exam preparation in 3rd year - you can now sit exams in Manila. For UAE/Singapore, ACCA or CPA credential opens doors significantly faster.', 'ASEAN MRA activated Jan 2025 - Philippine CPAs can register as RFPA in Singapore/Thailand/ASEAN. US CPA exam now available in Philippines since July 2024. UAE fastest deployment (1-2 years). Big 4 intracompany transfer is most reliable USA/UK/AU pathway.')
