INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-001', 'BS Agribusiness', 'Multi-Interdisciplinary', 'INTERNATIONAL', 'Moderate', ARRAY['Netherlands', 'Canada', 'Australia', 'Philippines', 'UAE (agrifood trade)'], FALSE, 'None (Agriculturist Licensure Exam covers Agriculture, not Agribusiness)', 4, 'The Wageningen University MSc program in Management of Agro-Food Chains is the gold standard for international agribusiness careers. Apply for the NFP (Netherlands Fellowship Programme) scholarship for Filipino government employees, or Orange Knowledge Programme (OKP). If going to industry directly, Cargill Philippines, San Miguel Foods, and Del Monte Philippines are strong employers with international transfer potential. For commodity trading, study CFA (Chartered Financial Analyst) alongside your degree.', 'Agribusiness has better international mobility than pure Agriculturist because it combines business/management skills with agricultural knowledge. The key differentiator from a pure agriculture degree is the supply chain, commodity trading, and agri-finance competency. The Netherlands is the global hub for agrifood innovation — Wageningen University & Research (WUR) is ranked #1 globally for Agriculture and Forestry; Dutch agribusiness companies (Rabobank, FrieslandCampina, Unilever Food, Yara International fertilizers) hire agribusiness graduates. Canada has growing agrifood sector with immigration pathways through Saskatchewan, Manitoba, and Alberta agricultural programs. Australian ACIAR research collaborations sometimes hire Filipinos for project-based roles. For domestic graduates: the biggest multinationals in PH agribusiness (Del Monte, Dole, San Miguel Agri, Jollibee Foods procurement, ANFLO Group) offer competitive corporate careers. Commodity trading is an underexplored pivot — major trading houses (Cargill, Louis Dreyfus, Olam) hire Filipino agribusiness graduates for grain/sugar/coconut oil trading desk analyst roles.')
