INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-013', 'BS Agriculture', 'Multi-Interdisciplinary', 'DOMESTIC', 'Moderate', ARRAY['Japan', 'Israel', 'Australia'], TRUE, 'Agriculturist Licensure Exam (ALE)', 4, 'Add HACCP and ISO 22000 food safety certifications - these are internationally portable and open UAE/Saudi QA roles paying $2,200-$4,100/month. Japan SSW pays ~$1,100-$1,450/month and doesn''t leverage your degree.', 'Philippine Agriculturist license has no bilateral mutual recognition internationally. Semi-skilled OFW programs (Japan SSW, Israel bilateral) do NOT leverage the degree. Graduate-level international roles require master''s degree or food safety certifications (HACCP, ISO 22000).')
