INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-002', 'BS Agro-Forestry', 'Multi-Interdisciplinary', 'RESEARCH_FIRST', 'Low-Moderate', ARRAY['Philippines', 'Kenya (ICRAF/CIFOR)', 'Indonesia', 'Netherlands', 'Germany'], FALSE, 'None (Forester Licensure Exam is separate; Agro-Forestry is distinct from BS Forestry)', 4, 'A Master''s degree is essentially mandatory for meaningful international career progression in this field. Apply for CGIAR internship programs early — CIFOR-ICRAF hosts graduate students and interns from UPLB and CLSU regularly. The REDD+ / carbon offset angle is your fastest-growing pathway without a Master''s — voluntary carbon market developers (South Pole, Verra, Gold Standard) hire agroforestry specialists to design and verify tree-planting projects. FAO Junior Professional Officer (JPO) programs open doors after 2-3 years of experience.', 'Agro-Forestry is a highly specialized field with limited direct international employment pathways at the bachelor''s level. The international career requires a Master''s degree — ideally from Wageningen (Netherlands), University of Copenhagen, or ANU (Australia). The main international employers are CGIAR (Consultative Group on International Agricultural Research) system organizations, particularly CIFOR-ICRAF (the merged Center for International Forestry Research and World Agroforestry). ICRAF''s Bogor, Indonesia facility is relatively accessible for Filipino graduates. FAO''s forestry programs in Rome and regional offices hire agroforestry specialists. Domestically, DENR''s Forest Management Bureau, DA''s National Agro-Forestry Program, and UPLB-based research are the entry points. Carbon offset/REDD+ programs are a growing pathway — agroforestry systems are used for carbon sequestration projects financed by international carbon markets. This is an emerging area with real income potential in climate finance.')
