INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-001', 'BS Applied Mathematics', 'Science & Math', 'INTERNATIONAL', 'High', ARRAY['USA', 'Singapore', 'UK', 'Canada', 'Remote (Global)'], FALSE, NULL, 4, 'Learn Python and SQL before graduation. Build a Kaggle portfolio or GitHub repo. Apply directly to Singapore-based fintech or tech companies (no lottery system unlike USA). Actuarial science is a natural adjacent career: passing CAS or SOA actuarial exams (done in Philippines) dramatically opens USA, Canada, and Bermuda insurance markets.', 'Applied Mathematics is one of the most internationally transferable science degrees. The key pivot: the degree title matters less than demonstrated skills. Most successful international hires from this course work as Data Scientists, Quantitative Analysts, Actuarial Analysts, Operations Research Analysts, or Software Engineers. Pure mathematician roles abroad are almost exclusively PhD-track. With a BS and programming skills (Python, R, SQL), direct employment in tech and finance internationally is very achievable, including remote-first roles. Singapore and UK have formal visa categories for mathematical sciences occupations. USA is the highest-ceiling destination but requires H-1B sponsorship (lottery). Remote work for US or EU tech companies is the fastest entry point for fresh graduates.')
