INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-002', 'BS Applied Physics', 'Science & Math', 'INTERNATIONAL', 'Medium', ARRAY['Netherlands', 'Germany', 'South Korea', 'USA', 'Japan'], FALSE, NULL, 4, 'Specialize in semiconductor physics, optics, or medical imaging during your electives. Learn Python or MATLAB for data analysis. Taiwan''s Gold Card visa actively targets STEM professionals: apply after 2 years of relevant experience. ASML in the Netherlands has a graduate program worth targeting. Avoid the academic physicist path unless you want a PhD — industry is where the international BS-level jobs are.', 'Applied Physics has a real industry pathway through the global semiconductor and medical device sectors — this distinguishes it from pure theoretical physics. The key employers internationally are semiconductor fabs (TSMC, Samsung, ASML, SK Hynix, Intel) and medical device companies (Medtronic, Philips, Siemens Healthineers). Most BS-level roles are process engineer, R&D technician, quality engineer, or equipment engineer — not physicist roles per se. A master''s in semiconductor engineering, materials science, or photonics significantly accelerates access. The Netherlands is notable because ASML (the world''s monopoly maker of EUV lithography machines) is headquartered in Eindhoven and actively recruits globally. South Korea and Taiwan are the fastest entry points because their semiconductor fabs directly recruit Filipinos for technician and process roles. Purely academic or research physics roles (CERN, NIST, national labs) require a PhD.')
