INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-004', 'BS Applied Statistics', 'Science & Math', 'INTERNATIONAL', 'High', ARRAY['USA', 'Canada', 'UK', 'Singapore', 'Remote (Global)'], FALSE, NULL, 4, 'Learn Python (pandas, scikit-learn), SQL, and R before graduation. Get a Kaggle competition ranking. Biostatistics is a high-value niche: if you can pair stats with clinical trial methodology (GCP certification is free online), pharma companies in Ireland and Singapore will hire you with a BS. Remote contract work through Toptal or LinkedIn is the fastest way to start earning international rates from the Philippines.', 'BS Applied Statistics is arguably the most internationally employable pure-science degree from the Philippines right now. The global demand for data analysts, data scientists, and statisticians vastly exceeds supply. Filipino graduates with Python, R, SQL, and statistics skills are directly competitive in international and remote job markets without additional credentials. Key roles: Data Analyst, Data Scientist, Business Intelligence Analyst, Biostatistician, Quantitative Researcher, Actuary (with additional exams). The remote-first tech economy means many US and EU companies hire Filipino statisticians on contractor basis — fastest path to international income. Government statistical offices in Canada (Statistics Canada), Australia (ABS), and UK (ONS) all hire statisticians and have immigration pathways. Clinical trials or biostatistics is a niche with very high demand in USA, UK, and Switzerland (pharma sector).')
