INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('ARCH-001', 'BS Architecture', 'Architecture', 'INTERNATIONAL', 'High', ARRAY['UAE', 'Saudi Arabia', 'Australia', 'Canada', 'USA'], TRUE, 'Architect Licensure Exam (ALE)', 5, 'Pass ALE before graduating or within 1 year — it is your biggest salary differentiator abroad. Target UAE/Dubai for fastest entry and best first-3-years income. Build BIM (Revit/ArchiCAD) skills — Gulf firms specifically require this. After 3-5 years Gulf experience, USA or Australia become realistic with your accumulated portfolio.', 'Gulf (UAE/Saudi) is the largest and fastest immediate employer of Filipino architects — no licensing exam required, only employer sponsorship and SoE registration. Australia has strong demand and a structured pathway (AACA + APE), with architects on the skilled occupation shortage list. USA pathway requires completing NCARB''s Architectural Experience Program (AXP, min 3,740 hours) and passing 6-division ARE — Filipino architects commonly work as ''architectural staff'' while accumulating hours. UK requires ARB Part 3 equivalent; no MRA currently exists between Philippines and UK, so international assessment route applies. Canada requires CACB academic assessment plus Internship in Architecture Program (IAP). NEOM mega-project in Saudi Arabia is actively hiring architects at premium packages (SAR 200k-400k/yr).')
