INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-003', 'BS Biochemistry', 'Science & Math', 'INTERNATIONAL', 'Medium', ARRAY['Switzerland', 'USA', 'Singapore', 'Ireland', 'UK'], FALSE, NULL, 4, 'If you want pharma industry internationally: pursue QC or QA or Validation Engineer roles, not research scientist roles — these do not require a PhD and Ireland and Singapore are hiring Filipinos. If you want research: plan for a master''s abroad — fully funded programs exist in Germany, Netherlands, and UK. MedTech license (Philippines) plus biochemistry equals medical lab scientist pathway to Australia, Canada, and UK. Pre-med remains the highest-ceiling career pivot.', 'HONEST ASSESSMENT: For most international research scientist roles at Big Pharma (Pfizer, Novartis, Roche, AstraZeneca), a master''s or PhD is the de facto requirement. A BS in Biochemistry from the Philippines primarily opens doors in: (1) Pharmaceutical QC or QA analyst roles — these are achievable with a BS and are internationally deployable. (2) Clinical laboratory work — requires additional credentials such as MedTech license or equivalent abroad. (3) Food science or quality assurance in food manufacturing. (4) Career pivot to medical school: BS Biochemistry is excellent pre-med preparation. The most direct international BS-level pathway is QC or QA Analyst at pharmaceutical manufacturing plants, particularly in Ireland (where Pfizer, J&J, Amgen, Lilly all have large manufacturing sites that actively recruit Filipinos) and Singapore (Biopolis biotech hub). Ireland is the single most accessible direct pathway for Filipino biochemistry graduates: multiple pharmaceutical manufacturers and a straightforward Critical Skills permit process.')
