INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-005', 'BS Biology', 'Science & Math', 'DOMESTIC', 'Low-Medium', ARRAY['USA (via medical school)', 'Canada', 'Australia', 'UK', 'UAE'], FALSE, NULL, 4, 'Decide early: pre-med (aim for UP PGH, UERM, or Cebu Doctors), or science research track. If research track, plan for a master''s abroad — DOST-funded scholarships exist. If pharma sales abroad is the goal, pharmaceutical companies in UAE, Singapore, and Malaysia hire Filipino BS Biology graduates as medical representatives — no additional credential needed, but communication skills and product knowledge are key.', 'HONEST ASSESSMENT: BS Biology is primarily a domestic career in the Philippines — DOST researcher, DENR, academe (instructor), pharmaceutical lab assistant, or pre-med prerequisite. The degree by itself has very limited direct international OFW pathways. The high-value international paths all require either: (1) Medical school (MD) then USMLE for USA, AMC for Australia, PLAB for UK; (2) Graduate school (master''s or PhD) for research roles; (3) Career pivot to MedTech (1-year conversion or dual program) for lab science work abroad; (4) Pharmaceutical sales or medical representative — achievable with BS Biology plus sales skills, active in Gulf, Singapore, and Malaysia. Filipino biology graduates working internationally are overwhelmingly either doctors, nurses (via re-course), MedTechs, or pharma sales reps — not biologists per se. The DOMESTIC tag reflects that the direct BS Biology pathway to OFW work is weak; the pivots are the real pathways.')
