INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-006', 'BS Botany', 'Science & Math', 'DOMESTIC', 'Low', ARRAY['Australia', 'Canada', 'Netherlands', 'USA (via graduate school)'], FALSE, NULL, 4, 'Pair botany with GIS (Geographic Information Systems) skills — this pivots you to environmental consulting and land management roles that do exist internationally. Consider master''s programs in Conservation Biology, Agroforestry, or Plant Biotechnology at Wageningen University (Netherlands, globally top in agricultural science) — most programs are in English. CGIAR centers offer internships that convert to staff positions for qualified candidates.', 'HONEST ASSESSMENT: BS Botany has the narrowest international career pathway of all courses in this cluster. The degree is primarily domestic: DOST, DENR, PCAARRD, NSCB, or academe. International opportunities exist, but almost all require either (a) a graduate degree (master''s or PhD) for research roles, or (b) a career pivot into allied fields (agriculture, environmental science, ecotourism management). The most realistic international paths for a BS Botany graduate: (1) CGIAR research centers — these are international agricultural research organizations with positions in developing countries, but most research positions require master''s or PhD. (2) Environmental impact assessment consulting in Australia or Canada — possible with additional environmental science training. (3) Seed company or agricultural biotechnology industry (Syngenta, Corteva, Bayer CropScience) — possible with BS in a QA or field technician role, but limited. Pure botanist is not an internationally recruited profession outside academia.')
