INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-006', 'BS Business Administration (BSBA)', 'Business & Management', 'INTERNATIONAL', 'Moderate', ARRAY['Canada', 'Australia', 'UAE', 'Singapore', 'UK'], FALSE, NULL, 4, 'BSBA is versatile but you must pick a lane. Supply Chain is the highest-paying international track — Canada and Australia actively recruit. Marketing is increasingly remote-work friendly. HR in multinationals is a solid Singapore/UAE path. If not specialized: the Gulf OFW pathway (UAE, Qatar, Saudi) is fast and reliable for restaurant/retail management. Get one professional certification in your specialization: PMP, CSCP, or SHRM-CP.', 'BSBA is the broadest business degree — international success depends almost entirely on specialization chosen. Top international pathways by specialization: (1) Operations/Supply Chain: Canada and Australia have strong demand — supply chain manager median CAD 137,000 in Canada, AUD 145,000 in Australia. (2) HR Management: Multinational HR roles in Singapore, UAE; HR BPO sector growing. (3) Marketing: Digital marketing roles globally; SEO/paid media open to remote work. (4) Entrepreneurship/General Management: OFW pathway via retail/restaurant management in Gulf, US, Canada. Note: Many BSBA graduates take OFW routes as service crew, store managers, restaurant supervisors — these are legitimate, well-paying paths especially in Gulf states. Gulf entry-level service/management roles: USD 18,000-35,000 tax-free. Canada/Australia skilled migration for management roles: USD 50,000-75,000+ starting.')
