INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('BUS-002', 'BS Business Analytics', 'Business & Management', 'INTERNATIONAL', 'Very High', ARRAY['Singapore', 'USA', 'Australia', 'Canada', 'UK'], FALSE, NULL, 4, 'Master the toolkit: SQL, Python, Tableau or Power BI, and one cloud platform (AWS or Azure). Singapore is the fastest path — Employment Pass leads to PR in 2-3 years. Australia offers the clearest permanent residency pathway via skilled migration. Remote work for US companies is viable from Day 1 with 2-3 years of experience.', 'One of the hottest global fields. Filipino graduates with SQL, Python, Tableau, Power BI, and machine learning skills are globally competitive. Singapore entry-level data analysts earn SGD 48,000-58,000/yr (~USD 35,000-43,000). Australia average AU$72,808/yr (~USD 47,000). USA entry-level USD 56,000-75,000. Remote roles for US/EU companies pay USD 80,000-120,000+. Australia PR pathway via CSOL list is strong — 30%+ job growth projected 2026-2030. Singapore Employment Pass requires minimum SGD 5,000/month (2025 threshold). Canada median supply chain/analytics consultant ~CAD 81,000.')
