INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-007', 'BS Chemistry', 'Science & Math', 'INTERNATIONAL', 'Medium-High', ARRAY['UAE', 'Saudi Arabia', 'Australia', 'Canada', 'USA'], TRUE, 'PRC Chemist Licensure Exam (CLE)', 4, 'Pass the CLE — it matters internationally, especially in the Gulf. Target petrochemical plant QC or QA roles in UAE or Saudi Arabia as a first posting. Gulf experience plus 2-3 years leads to credentialing for Australia (VETASSESS plus skills assessment) or Canada (Express Entry). Royal Society of Chemistry (RSC) membership can be obtained from the Philippines and is recognized in UK and internationally — start the application process early.', 'BS Chemistry with PRC board license has better international deployability than most pure science courses because the industrial chemistry sector (petroleum, petrochemicals, pharmaceuticals, food processing, mining) has real international demand. The Gulf states (UAE, Saudi, Qatar, Kuwait) represent the most accessible immediate destination: petrochemical companies (SABIC, ADNOC, QatarEnergy) and pharmaceutical manufacturing plants hire chemists at BS level. Australia has strong demand in mining or resources chemistry and food safety. Canada''s mining and oil sands sector is another route. Pure research chemistry is dominated by PhD-holders internationally. The PRC license is recognized as a base credential in Gulf states — unlike many Philippine professional licenses, it is actually helpful abroad. The board exam has national pass rates around 30-40%, so the PRC license itself signals competency internationally.')
