INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-003', 'BS Climate Change / Climate Change Adaptation', 'Multi-Interdisciplinary', 'INTERNATIONAL', 'Moderate-High', ARRAY['South Korea (GCF)', 'Germany (UNFCCC)', 'Singapore (ESG hub)', 'USA', 'Philippines (PAGASA/CHED/LGUs)'], FALSE, NULL, 4, 'Get your CFA ESG Certificate ($355, online exam) — it is increasingly required for ESG finance roles. Learn to use climate modeling tools (QGIS for mapping, R for climate data analysis, or Python). The GCF in South Korea runs competitive internship programs specifically for developing country nationals — apply in your 3rd or 4th year. Singapore''s MAS Green Finance programs are actively recruiting climate-trained professionals across Southeast Asia. A Master''s in Climate Change Policy (UK: Oxford, Edinburgh, UCL) or Environmental Management (NUS Singapore) significantly upgrades your trajectory.', 'Climate Change as a degree is relatively new but the career demand is explosively growing. The Glasgow COP26 (2021), Dubai COP28 (2023), and Baku COP29 (2024) commitments created billions in new climate finance flows requiring professional management. The Green Climate Fund (GCF) in Incheon, South Korea is the world''s largest dedicated climate fund ($13.6B pledged) and actively hires climate professionals from developing countries — including Filipinos. ESG (Environmental, Social, Governance) consulting is the fastest-growing career track in global finance and management consulting — major firms (McKinsey, BCG, Deloitte, PwC, EY) have massive sustainability practices. Singapore is Asia''s ESG hub with MAS (Monetary Authority of Singapore) driving sustainable finance regulations. The Philippines itself is uniquely positioned — as one of the most climate-vulnerable countries globally, PH has exceptional credibility in international climate negotiations. PAGASA, CHED Climate Change programs, CCC (Climate Change Commission), and NEDA environmental division are domestic entry points.')
