INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-001', 'BS Community Development', 'Social Sciences', 'DOMESTIC', 'Low', ARRAY['Philippines', 'Kenya', 'Ethiopia', 'Indonesia', 'Bangladesh'], FALSE, NULL, 4, 'If international development work is your goal, treat your BS Community Development as the first step, not the destination. Plan for a master''s degree (MPA or MSW from a reputable school) and target the UN Volunteers programme for your first international posting. Build measurable project impact data from day one — INGOs and the UN want to see numbers (beneficiaries reached, funds managed, community outcomes).', 'Community Development is overwhelmingly a domestic career in the Philippines. The international pathway exists but is highly competitive and indirect: (1) Work 3-5 years in PH with a credible INGO (CARE, Save the Children, World Vision PH office), build a strong portfolio of project results, then apply for international postings. (2) UN Volunteers (UNV) programme is the most accessible entry point — pays a living allowance (~$1,500-2,500/month), no salary, but counts as UN experience. (3) After UNV assignment, competitive for junior Professional Officer (JPO) or national officer roles within UN system. (4) Master''s degree (MSW, MPA, MPH, or M.Community Development) dramatically improves competitiveness for P-level UN posts. Starting salary abroad: INGO field staff $28,000-45,000; UN national professional officer $40,000-65,000; UN P-3 international staff $90,000+ (but very few slots). Honest assessment: most CD graduates work in LGU social welfare departments, DSWD, or local NGOs. International career is a 7-10 year project requiring master''s + INGO experience.')
