INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('IT-001', 'BS Computer Science', 'Information Technology', 'INTERNATIONAL', 'Very High', ARRAY['USA', 'Canada', 'Singapore', 'Remote (Global)', 'Australia'], FALSE, NULL, 4, 'Build a GitHub portfolio while still in school. Contribute to open-source. Get one cloud cert (AWS Solutions Architect Associate) before graduation. These three things unlock remote work within 3-6 months of graduation and bypass the entire visa-and-sponsorship system.', 'CS is the single most internationally mobile non-healthcare Philippine degree. Three parallel tracks exist: (1) Remote work from PH for US/EU employers — no relocation, USD/EUR rates; (2) Singapore/Gulf deployment — fastest physical relocation; (3) USA/Canada/Australia — highest ceiling but longer process. The Philippines IT-BPM industry (PEZA-registered BPOs and GICs) also absorbs large numbers; distinguish between working FOR a foreign company locally (IT-BPM) vs. BEING foreign-deployed. Remote work is increasingly the primary ''international'' pathway without physically moving.')
