INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-003', 'BS Criminology', 'Social Sciences', 'INTERNATIONAL', 'Moderate', ARRAY['UAE', 'Canada', 'Australia'], TRUE, 'Criminologist Licensure Exam (CLE)', 4, 'PH Criminology license alone won''t get you international policing. Target either security management (ASIS CPP certification) or forensic science (additional lab credentials).', 'Philippine RCrim license does NOT qualify for direct foreign police entry - citizenship required. International pathways: private security management (Gulf), forensic science (USA/AU/UK), corrections (Canada/Australia), digital forensics (global/remote). ASIS CPP/PSP certifications are globally portable.')
