INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('TEA-001', 'BS Culture and Arts Education', 'Teacher Education', 'DOMESTIC_FIRST', 'Moderate', ARRAY['Philippines', 'UAE', 'Singapore', 'UK', 'International (IB Schools Worldwide)'], TRUE, 'Licensure Exam for Teachers (LET) - Elementary', 4, 'Get your LET first, then build a strong digital portfolio of student work and your own creative output. Pursue IB Category 1 workshop training (available online via IBO). The UAE and Qatar international school market actively recruit arts specialists — GEMS Education, Taaleem, and Aldar Academies are top hirers. Salary in UAE is tax-free.', 'Culture and Arts Education has a niche but real international pathway through international and IB schools, which actively recruit specialist arts teachers. The IB (International Baccalaureate) Diploma Programme includes Visual Arts, Music, and Theatre as standalone subjects — creating demand for specialist Arts educators at 5,000+ IB schools worldwide. The UAE has 600+ international schools with active arts programs. Domestic demand remains strongest due to the DepEd MAPEH program. Graduates can also pivot into arts administration, cultural tourism, museum education, and creative industries management. The British Council''s global arts education programs sometimes recruit Filipino arts educators for project-based work. Career ceiling internationally is moderate — arts teachers are in less acute shortage than STEM or SPED teachers, so strong portfolio and IB PYP/MYP/DP training certification are differentiators.')
ON CONFLICT (course_id) DO UPDATE SET
