INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('IT-002', 'BS Cyber Security', 'Information Technology', 'INTERNATIONAL', 'Very High', ARRAY['USA', 'Remote (Global)', 'Australia', 'Canada', 'UK'], FALSE, NULL, 4, 'Start TryHackMe or HackTheBox in Year 1. Get CompTIA Security+ BEFORE graduation — it is the global entry-level standard and requires no experience. CEH (Certified Ethical Hacker) needs 2 years experience but looks excellent on a resume. CISSP requires 5 years but is the gold standard for management tracks.', 'Cybersecurity is experiencing a global workforce shortage of 3.5 million unfilled positions (ISC2 2024 Workforce Study). Unlike general software development, cybersecurity roles are less susceptible to AI replacement and often require government security clearances (USA, Australia, UK) or industry certifications that are globally standardized. Filipino BS Cybersecurity graduates are entering a field where demand dramatically outpaces supply. The three pillars: certifications (CompTIA Security+, CISSP, CEH), hands-on lab experience (TryHackMe, HackTheBox), and portfolio (CTF wins, bug bounty finds). Government/defense sector pays premium but requires citizenship in most Western countries.')
