INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-004', 'BS Data Science and Analytics', 'Multi-Interdisciplinary', 'INTERNATIONAL', 'Very High', ARRAY['USA', 'Singapore', 'UK', 'Australia', 'Remote (Global)'], FALSE, 'None (ECE board not applicable; Data Science has no PRC board)', 4, 'Build a GitHub portfolio immediately — every project counts. Join Kaggle competitions to demonstrate skills publicly. The remote work pathway is your fastest route to international compensation without migrating: Philippine-based Filipino data scientists working for US startups routinely earn PHP 100,000-200,000/month. For Singapore, the MAS TechUp initiative and MoneySense fintech programs create data science demand. For USA, H-1B is challenging (lottery) but employer-sponsored options exist for specialist roles. The cloud certification (AWS/GCP) costs $300-600 and dramatically increases your hirability globally.', 'Data Science and Analytics is one of the most internationally mobile degrees available today, with the added benefit of massive remote work potential. Unlike most other careers in this research, Data Scientists can command international salaries while physically remaining in the Philippines — remote-first companies (fully remote startups, US tech companies with offshore teams, UK fintech firms) regularly hire Filipino data scientists at USD 24,000-60,000+/year, far exceeding comparable local salaries. In-person migration destinations are led by the USA (Silicon Valley, NYC fintech, Seattle tech), Singapore (Asia''s tech hub, data-intensive fintech/logistics/government), and UK (London fintech, Edinburgh financial analytics). Australia has strong demand in mining analytics, financial services, and health data. Canada''s tech corridor (Toronto-Waterloo, Vancouver) is accessible via Express Entry. The Philippine domestic market is also growing rapidly — BPO industry evolving to data analytics services, DICT programs, and multinational Philippine data centers. Key insight: this is the only degree in this entire research where the remote work pathway genuinely rivals or exceeds the migration pathway in early-career compensation.')
