INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-005', 'BS Disaster Risk Management (DRRM)', 'Multi-Interdisciplinary', 'DOMESTIC_FIRST', 'Moderate', ARRAY['Philippines (NDRRMC)', 'Switzerland (IFRC/WMO)', 'USA (USAID/FEMA)', 'Japan (JICA/ADRC)', 'UN Global (OCHA/UNDP)'], FALSE, NULL, 4, 'Work with Philippine Red Cross or a local DRRM office first — 2-3 years of documented field experience is what separates you from international competitors. The OCHA Field Coordination Training Programme (FCTP) is a key credential. Sphere Handbook knowledge is expected. Learn GIS (QGIS/ArcGIS) for disaster risk mapping — it is increasingly required. Japanese ADRC in Kobe runs fellowships specifically for Asian DRRM practitioners. The JPO (Junior Professional Officer) programme is the main UN entry pathway — DOST/DILG Philippines sponsors nominees.', 'DRRM is a field where Philippine graduates have genuine competitive advantages internationally — the Philippines is one of the world''s most disaster-prone countries and among the most experienced in disaster response. Filipino DRRM practitioners have real-world expertise that is highly credible in international organizations. However, the career path has a clear pattern: most meaningful international roles (OCHA, UNDP, IFRC at operational level) require 3-5 years of domestic/field experience first. Entry-level international positions are competitive and relatively few. The humanitarian sector uses a ''humanitarian system'' of career ladders: internship ? junior professional officer (JPO, typically government-sponsored) ? national professional officer (NPO) ? international professional. The fastest domestic entry is via NDRRMC, LGU DRRM offices, OCD (Office of Civil Defense), DSWD emergency response, or Philippine Red Cross. Climate change is accelerating demand — the IPCC estimates DRR-related employment needs will grow significantly through 2030. Typhoon, earthquake, and flooding response expertise from the Philippines is genuinely valued globally.')
