INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('TEA-002', 'BS Early Childhood Education (ECE)', 'Teacher Education', 'INTERNATIONAL', 'Very High', ARRAY['UAE', 'Saudi Arabia', 'UK', 'Singapore', 'Qatar'], TRUE, 'Licensure Exam for Teachers (LET) - Elementary', 4, 'Pass your LET as early as possible. Then take a UK EYFS online course (many available from UK providers like Highfield or CACHE) to show familiarity with the international standard. Filipino teachers in UAE Kindergartens regularly earn AED 6,000-10,000/month ($1,600-2,700) tax-free — far more than DepEd salaries. Apply through Teach Away, Search Associates, or directly to GEMS and Taaleem school groups.', 'ECE is one of the strongest OFW teacher pathways. The Gulf states have massive demand for qualified kindergarten and nursery teachers for expat community international schools. UAE alone has 200,000+ school-age expat children requiring EYFS-based or play-based early education. Filipino ECE teachers are specifically sought for their warmth, English proficiency, and patience. The UK EYFS (Early Years Foundation Stage) framework is the gold standard internationally — many international schools in Asia and the Middle East follow it. Filipino ECE graduates can get UK QTS recognition through the iQTS route or work as Early Years Practitioners without full QTS in UK nurseries. Australia''s ACECQA (Australian Children''s Education & Care Quality Authority) process recognizes PH ECE degrees with some bridging requirements. Key advantage: ECE demand grows with expatriate population growth in Gulf — this is a steady and growing market for Filipinos.')
