INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('ARCH-002', 'BS Environmental Planning', 'Architecture', 'INTERNATIONAL', 'Moderate', ARRAY['Philippines (domestic focus)', 'Canada', 'Australia', 'USA', 'International Orgs (World Bank', 'ADB', 'UN-Habitat)'], TRUE, 'Environmental Planner Licensure Exam (EnPLE)', 5, 'Master GIS (ArcGIS, QGIS) and climate-resilience planning tools — these are the most in-demand skills in international development orgs. A master''s degree in Urban Planning (UP Diliman, or abroad) dramatically improves World Bank/ADB competitiveness. AICP certification unlocks USA urban planning jobs.', 'BS Environmental Planning is primarily a domestic profession in the Philippines (tied to HLURB/DHSUD, LGU comprehensive land use plans). International pathways exist but require repackaging skills: urban planning, land use, EIA, GIS, climate resilience. Top international pathway is through multilateral development organizations (World Bank, ADB, UN-Habitat, UNDP) — highly competitive but prestigious. Australia and Canada have active urban planning markets. PIEP has Saudi and Qatar chapters — indicating Gulf demand. EnP graduates can also enter the Gulf as ''urban planning consultants'' on project-based contracts.')
