INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-008', 'BS Environmental Science', 'Science & Math', 'INTERNATIONAL', 'Medium-High', ARRAY['Canada', 'Australia', 'UK', 'Netherlands', 'UAE'], FALSE, NULL, 4, 'Get NEBOSH IGC certification before graduation or during your first year of work — it costs about PHP 40,000-60,000 but is recognized in UAE, UK, Australia, and Singapore. ISO 14001 Lead Auditor certification is another high-value add. Target EIA consulting firms in UAE as first posting — experience on large infrastructure projects is globally transferable. ESG analyst roles are increasingly remote-friendly.', 'Environmental Science has genuine and growing international demand driven by: (1) ESG (Environmental, Social, Governance) reporting requirements for corporations globally — demand for environmental auditors and sustainability analysts. (2) Environmental Impact Assessment (EIA) — required for infrastructure projects globally; high demand in UAE and Saudi Arabia and Australia for major construction programs. (3) Climate change consulting and carbon market work. (4) Environmental compliance for mining, oil and gas, and real estate sectors. The most accessible international path for a fresh graduate is Environmental or HSE Officer or EIA Consultant in the Gulf (UAE, Saudi) where massive infrastructure projects (NEOM, Vision 2030) require constant environmental assessment. Canada is the best long-term destination due to its immigration points system favorability for environmental scientists and genuine environmental protection sector. The NEBOSH IGC (International General Certificate — Health, Safety, Environment) is a globally recognized professional certification achievable in the Philippines and dramatically boosts employability internationally.')
