INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-005', 'BS Finance', 'Business & Management', 'INTERNATIONAL', 'High', ARRAY['Singapore', 'UAE (Dubai DIFC)', 'UK', 'Hong Kong', 'USA'], FALSE, NULL, 4, 'Start CFA Level 1 in your 3rd or 4th year of college — you can take it without a degree. Pass CFA Level 1 before graduation; this immediately makes you competitive for analyst roles in Singapore and Dubai. Dubai DIFC is the fastest high-paying destination (tax-free). Singapore requires Employment Pass threshold (SGD 5,000+/month) so CFA Level 1 helps justify higher starting offer. For Islamic finance specialty: add IFQ certification alongside CFA.', 'BS Finance is among the highest-ceiling non-board courses for international careers. CFA charterholder average Singapore salary USD 107,493 (entry USD 76,073). Dubai entry-level finance AED 120,000-180,000/yr (~USD 32,000-49,000) tax-free. Dubai investment banking analyst AED 240,000-420,000/yr (~USD 65,000-114,000) at bulge bracket banks. London mid-level CFA GBP 80,000-100,000+/yr. Singapore financial analyst entry SGD 60,000-90,000/yr. HK entry HKD 30,000-50,000/month. CFA Level 1 alone is a strong signal for entry-level roles — do not wait for full charterholder status. DIFC has 3,000+ registered companies; Islamic finance is a growing specialty.')
