INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('ARCH-003', 'BS Fine Arts (BFA)', 'Architecture', 'REMOTE', 'Moderate', ARRAY['USA', 'Canada', 'Singapore', 'Japan', 'Remote (Global)'], FALSE, NULL, 4, 'Your portfolio is your passport. Build a professional digital portfolio (ArtStation, Behance) while still in school. Master one digital tool deeply (Procreate, Photoshop, Clip Studio Paint, Blender). Freelance on Fiverr/Upwork from Year 2 — international clients pay 5-10x PH rates. Target Canadian animation studios or Singapore studios for first full-time abroad role.', 'BS Fine Arts has no standard OFW pathway like nursing or engineering. However, strong international income streams exist through: (1) FREELANCE — digital illustration, concept art, graphic design on Upwork/Fiverr with global clients paying USD rates (2) ANIMATION STUDIOS — Canada (Ottawa/Vancouver), USA (California), Singapore, Japan hire Filipino animators and concept artists for film, TV, and gaming (3) GAME/CONCEPT ART — US gaming studios pay USD 60k-123k+ for concept artists; remote-first game studios increasingly common. NFT/digital art market has stabilized post-2022 peak but remains a revenue stream. Most impactful specializations: 2D/3D animation, concept art, character design, visual effects, UI/UX illustration.')
