INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-011', 'BS Fisheries Technology', 'Multi-Interdisciplinary', 'DOMESTIC', 'Moderate', ARRAY['Australia', 'Canada', 'UAE'], TRUE, 'Fisheries Technologist Licensure Exam (FTLE)', 4, 'Add HACCP, ISO 22000, and MSC Chain of Custody certifications. These are more internationally portable than your PRC Fisheries license and open UAE/Saudi seafood QA roles paying $1,360-$3,270/month.', 'BS Fisheries is primarily a domestic career track. PRC Fisheries Technologist license has no bilateral mutual recognition internationally. Most OFW placements are fish processing factory workers (degree not leveraged). Best route is seafood QA/food safety in Middle East or aquaculture science in Australia.')
