INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-012', 'BS Forestry', 'Multi-Interdisciplinary', 'DOMESTIC_FIRST', 'Low-Moderate', ARRAY['Philippines (DENR/PAWB)', 'Japan (ITTO)', 'USA (USDA Forest Service/conservation NGOs)', 'Canada', 'FAO Rome'], TRUE, 'Forester Licensure Examination (PRC)', 4, 'Pass the PRC Forester board and get at least 2 years DENR/PAWB fieldwork. Then pursue FSC Lead Auditor training ($500-1,000 course + assessment) — this makes you internationally deployable as a forestry auditor. ITTO''s fellowship program is specifically designed for Filipino forestry graduates — apply for the Young Expert and Fellowship programs. For REDD+ carbon projects, learn VCS (Verified Carbon Standard) methodology and MRV (Measurement, Reporting, Verification) techniques — this combination of Forester license + REDD+ expertise is what gets you hired by conservation organizations and carbon project developers globally.', 'BS Forestry with PRC Forester License primarily serves the domestic Philippine market — DENR and PAWB (Protected Areas and Wildlife Bureau) are the primary employers, along with the forestry sector of large landowners, plantation forestry companies, and wood processing industries. International career pathways exist but are distinctly specialized. ITTO in Yokohama specifically funds fellowships for developing country foresters. FAO''s Forestry Division in Rome employs tropical forestry specialists and Filipinos with DENR experience and ITTO fellowship backgrounds have been placed there. FSC (Forest Stewardship Council) chain-of-custody auditing is an internationally portable certification — FSC-certified auditors can work anywhere globally assessing sustainable forestry, timber supply chains, and pulp/paper operations. Canada''s RPF (Registered Professional Forester) designation is achievable with credential equivalency and there is active demand in BC and Alberta. Conservation NGOs (WWF, WCS, TNC, Wildlife Conservation Society) hire foresters for protected area management, REDD+ programs, and biodiversity offset projects. The carbon market angle is growing — tropical forests are major carbon sinks and REDD+ projects require forester verification expertise.')
