INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('IT-003', 'BS Game Development and Animation / Entertainment and Multimedia Computing', 'Information Technology', 'INTERNATIONAL', 'High', ARRAY['Canada (Montreal/Vancouver)', 'USA', 'Japan', 'Remote (Global)', 'Singapore'], FALSE, NULL, 4, 'Your portfolio IS your resume. Get it on ArtStation (animation/VFX) or itch.io (game dev). Join Global Game Jam (annual, January) to build a portfolio game with a team. For animation, learn Autodesk Maya, Blender, and Toon Boom Harmony — the industry trifecta. For game dev: Unity or Unreal Engine is mandatory; C# for Unity, C++ for Unreal.', 'This is the most portfolio-dependent IT cluster. Employers hire the demo reel and portfolio, not the degree. Philippine animation industry is a genuine springboard — the Philippines has a long history of animation outsourcing (animation for Warner Bros, Nickelodeon, Disney, DreamWorks produced in Manila). This creates a unique pathway: work in Philippine animation studio for 2—3 years, build credits on internationally recognized shows, then apply to international studios. Game development pathway is different — dominated by indie/mobile game scene in PH; AAA studio employment requires relocation to Canada, USA, or Japan. Three parallel tracks: (1) Animation: PH studio credits ? international studio; (2) Game dev: mobile/indie remote ? AAA studio relocation; (3) VFX/CG: PH VFX work (Synergy88, Toon City, Cloudpunk) ? international post-production.')
