INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-009', 'BS Geology', 'Science & Math', 'INTERNATIONAL', 'High', ARRAY['Norway', 'Australia', 'Canada'], TRUE, 'Geologist Licensure Exam (GLE)', 4, 'Petroleum geology or mining geology specialization pays 3x environmental geology. Build GIS and remote sensing skills - universally required for international geology roles.', 'Norway highest paying for petroleum geologists ($125k average). Australia critical minerals boom drives mining geologist demand. Canada has strong petroleum geology in Alberta. VETASSESS pathway (not Engineers Australia) for AU assessment.')
