INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('BUS-003', 'BS Hospitality Management', 'Business & Management', 'INTERNATIONAL', 'High', ARRAY['UAE', 'Saudi Arabia', 'Singapore', 'Japan', 'UK'], FALSE, NULL, 4, 'UAE and Gulf are the fastest track — agencies like POEA-accredited recruiters place fresh graduates in 3-4 months. Get a hotel brand certification (Marriott or Hilton online training) before applying. Cruise lines offer excellent savings since accommodation and food are provided. Target supervisor-level by Year 2 abroad.', 'Filipinos make up a large share of hospitality staff in UAE, Saudi Arabia, Singapore, and cruise lines globally. UAE: Front Office Agent AED 6,000-9,000/month (~USD 1,600-2,450), Restaurant Supervisor AED 7,000-10,000/month (~USD 1,900-2,700), F&B Manager AED 15,000-25,000/month (~USD 4,000-6,800). Tax-free income + free housing + free flights = high savings rate. Singapore: average USD 50,000/yr for mid-level roles, S Pass threshold SGD 3,150/month (Sep 2025). Saudi Arabia adding 25+ new luxury hotels 2025-2027 under Vision 2030. Cruise lines: USD 15,000-36,000/yr (Carnival/RCCL median ~USD 15,000 but includes free room/board/meals).')
