INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-010', 'BS Human Biology', 'Science & Math', 'DOMESTIC', 'Low-Medium', ARRAY['USA (via medical school)', 'Australia', 'UK', 'Canada', 'UAE (clinical or pharma adjacent)'], FALSE, NULL, 4, 'If you are not going to medical school, pursue the Clinical Research Coordinator path — it pays well and has genuine international demand from CROs like IQVIA, PPD, and Syneos Health. Get ACRP or SOCRA certification (can study online, exam fee approximately USD 400). IQVIA, Parexel, and Syneos Health all have regional offices in Asia and recruit Filipino CRCs for multinational trials. Public health master''s (MPH) abroad is another strong pivot — USAID, WHO, and CDC Foundation all hire Filipino MPH graduates.', 'HONEST ASSESSMENT: BS Human Biology (offered primarily at UP Diliman and a few other universities) is explicitly designed as a pre-medical degree. The primary pathway is medical school. Direct international employment with a BS Human Biology degree is very limited — the degree is not a recognized profession internationally the way nursing or medical technology is. However, career pivots accessible to Human Biology graduates include: (1) Clinical Research Coordinator (CRC) — growing field as clinical trials increasingly involve Filipino sites and contract research organizations (CROs). ACRP certification (obtainable in Philippines) opens CRC roles in USA, UK, and Singapore. (2) Pharmaceutical sales representative — achievable in Gulf or Singapore with this background. (3) Graduate school in Public Health, Epidemiology, or Biostatistics then international public health roles (WHO, WPRO, MSF, CDC Foundation).')
