INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-002', 'BS Human Services / Guidance and Counseling', 'Social Sciences', 'INTERNATIONAL', 'Moderate', ARRAY['UAE', 'Singapore', 'Saudi Arabia', 'Hong Kong', 'Qatar'], TRUE, 'Guidance Counselor Licensure Exam', 4, 'Pass the PRC Guidance Counselor board exam and gain 2-3 years experience in a Philippine school — ideally one with international curriculum exposure or a private school with diverse student populations. Then target international school job boards (TES/Times Educational Supplement, SearchAssociates, ISS staffing). A short CACREP-aligned certificate course online will strengthen your application. The Gulf has the largest number of openings and is the fastest deployment.', 'The primary international pathway for guidance counselors is school counseling at international schools in the Gulf and Asia. These schools (British, American, IB curriculum) actively recruit counselors who can support diverse international student bodies. Requirements typically include: bachelor''s degree in counseling/psychology/education, 2-3 years school counseling experience, English proficiency. The PRC Guidance Counselor license establishes professional credibility but is not directly recognized abroad — what matters is the degree, experience, and sometimes an international counseling credential (e.g., CACREP-accredited certificate program). Salary in UAE international schools: AED 8,000-14,000/month ($2,200-3,800/month, tax-free) = $26,400-45,600/year equivalent. Singapore international schools: SGD 48,000-70,000/year (~$36,000-52,000 USD). Qatar: QAR 12,000-18,000/month ($39,000-60,000/year). Housing and flights often included. Also growing: HR/employee assistance programme counselor roles at MNCs in Singapore and Hong Kong. Corporate wellness is a growing sector post-COVID.')
