INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-003', 'BS Indigenous Peoples Studies', 'Social Sciences', 'DOMESTIC', 'Very Low', ARRAY['Philippines', 'New Zealand', 'Canada', 'Australia'], FALSE, NULL, 4, 'If you are passionate about indigenous rights and want international exposure, plan for a PhD or master''s at a university with a strong Indigenous Studies program (University of British Columbia, University of Auckland, Australian National University). Alternatively, develop expertise in international indigenous rights frameworks (UNDRIP, ILO Convention 169) and position yourself as a policy specialist for Philippine government negotiations with UN bodies.', 'BS Indigenous Peoples Studies is the most domestically-focused degree in this cluster. The degree is essentially unique to the Philippines in this exact form — it is specifically designed for NCIP, IPRA (Indigenous Peoples Rights Act) compliance work, ancestral domain management, and IP community development in the Philippine context. International career is extremely limited and indirect. The countries where Indigenous Studies expertise translates internationally are Canada (First Nations/Metis/Inuit policy), New Zealand (Maori rights, Treaty of Waitangi), and Australia (Aboriginal affairs), but these countries have their own programs training their own graduates and rarely recruit internationally. Realistic international pathways: (1) UN Permanent Forum on Indigenous Issues (UNPFII) — intern/NGO participation track, usually voluntary or stipend-only; (2) INGO work in Indigenous advocacy (Survival International, Forest Peoples Programme) — typically UK/Europe-based organizations, require strong advocacy/communications skills; (3) Academic route — PhD in anthropology, indigenous studies, or related field at a Canadian or NZ university, which opens academic and policy positions. Honest assessment: 95% of career opportunities are in the Philippines. This degree is a genuine vocation for those committed to serving IP communities in PH.')
