INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('IT-004', 'BS Information Technology', 'Information Technology', 'INTERNATIONAL', 'High', ARRAY['Remote (Global)', 'UAE', 'Singapore', 'Canada', 'Australia'], FALSE, NULL, 4, 'Get AWS Solutions Architect Associate before graduation. It costs $300 to take but unlocks cloud roles starting at $60k remotely. CompTIA Network+ and CompTIA A+ are entry-level but widely recognized. For the IT-BPM/management track: ITIL 4 Foundation (service management) and PMP (project management) are the two most valuable certs for IT management internationally.', 'BS IT is the most commonly enrolled tech degree in the Philippines (hundreds of thousands of graduates annually) and has the broadest scope — it covers systems administration, networking, database management, business analysis, IT project management, and application development. The challenge is differentiation: BS IT is a generalist degree in a market that increasingly rewards specialization. The three best strategies for BS IT internationally: (1) Specialize early in cloud (AWS/Azure) — cloud skills are globally portable and immediately employable; (2) Add PMP or CAPM for project management track — opens IT-BPM leadership roles globally; (3) Pair with CISA for IT audit/governance track — opens Big 4 advisory roles internationally. BS IT graduates must understand: the degree alone does not command premium international salaries the way BS CS or specialized cybersecurity does. Certifications and demonstrated skills are mandatory differentiators.')
