INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('ARCH-004', 'BS Interior Design', 'Architecture', 'INTERNATIONAL', 'High', ARRAY['UAE', 'Saudi Arabia', 'Singapore', 'Australia', 'Canada'], TRUE, 'Interior Designer Licensure Exam (IDLE)', 4, 'Pass IDLE before going abroad — it is your proof of competency. Build a strong visual portfolio with renders and completed project photos. Master 3ds Max + AutoCAD + SketchUp. UAE/Saudi is the fastest entry — look for ''fit-out designer'' and ''FF&E designer'' roles at large project firms.', 'Interior design has strong Gulf demand driven by Saudi Vision 2030 fit-out projects, UAE luxury hospitality, and Qatar post-World Cup commercial development. IDLE-licensed Filipino interior designers are recognized as qualified professionals. In 2025, PRC established the IPID (Indonesia-Philippines Interior Designer) bilateral recognition agreement — first formal international MRA for interior designers. Australia (VETASSESS pathway) and Singapore (Employment Pass) are strong longer-term destinations. Mid-to-senior level designers command significant premiums. BIM/3D rendering skills (3ds Max, SketchUp, Revit) are key differentiators.')
