INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('ARCH-005', 'BS Landscape Architecture', 'Architecture', 'INTERNATIONAL', 'Moderate', ARRAY['Australia', 'UAE', 'Saudi Arabia', 'Canada', 'UK'], TRUE, 'Landscape Architect Licensure Exam (LALE)', 5, 'Get LALE licensure and then target Australia (AILA VETASSESS path) or UAE/Saudi (fastest entry). Specialize in sustainable/drought-tolerant design — this is critical for both Gulf arid climate and Australian water-sensitive design. Master AutoCAD + Lumion + GIS for strong applications.', 'Landscape architecture is a niche OFW pathway but offers real opportunities. Australia has ongoing shortages (AILA VETASSESS-endorsed pathway, visa subclasses 189/190/491 available). Gulf demand driven by NEOM''s ''zero-waste green city'' mandate, UAE parks/resort landscaping, and Saudi Vision 2030 greening projects. UK (BALI) and Canada (CSLA) are viable but slower. NEOM''s The Line, Sindalah island, and Leyja resort projects actively require landscape architects. Sustainable design and water-sensitive landscape design are the most in-demand specializations globally. New Zealand is NOT on the long-term skill shortage list for landscape architects (as of 2025 search data).')
