INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('IT-005', 'BS Library and Information Science', 'Information Technology', 'INTERNATIONAL', 'Moderate', ARRAY['Middle East (Saudi', 'UAE', 'Qatar)', 'USA', 'UK', 'Remote (Global)'], TRUE, 'Librarian Licensure Examination (LLE)', 4, 'The PRC Librarian License is your entry credential for the Middle East pathway. For USA/UK/Australia, you will need a master''s degree — either complete an MLS in the Philippines or pursue it abroad. Pivot toward information architecture, digital asset management, and knowledge management skills — these cross into corporate settings and pay significantly more than traditional library roles. The SLA (Special Libraries Association) has active Philippine chapter connections.', 'Library and Information Science has the narrowest international career pathway of all five IT courses — but niche real opportunities exist. The key distinction for LIS internationally: traditional librarianship (managing physical collections) vs. information management/knowledge management (digital, corporate, research settings). Digital transformation of libraries globally and the growth of knowledge management, corporate libraries, and information architecture roles create demand for LIS-trained professionals in non-traditional settings. The Middle East Gulf states (Saudi Arabia, UAE, Qatar) are the most accessible international destination for PRC Librarians — university libraries and corporate information centers in Gulf actively hire Filipino librarians. USA requires a Master''s of Library Science (MLS) from an ALA-accredited program for most professional roles — the BS LIS is not sufficient for US librarian positions. UK requires CILIP certification for Chartered Librarian status. International organizations (UN, World Bank, IMF, ADB) hire information professionals — highly competitive but real. Modern LIS graduates who develop data analytics, metadata/taxonomy, UX for digital libraries, and knowledge management skills have stronger international marketability than traditional cataloging-focused graduates.')
