INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-011', 'BS Marine Biology', 'Science & Math', 'DOMESTIC', 'Low', ARRAY['Australia', 'USA', 'New Zealand', 'UK', 'Norway'], FALSE, NULL, 4, 'Get AAUS Scientific Diver certification and PADI Divemaster or Instructor rating — this combination gives you international dive industry employment options. Australia''s Great Barrier Reef Marine Park Authority and AIMS both hire field technicians with strong dive credentials. If you genuinely want to be a marine biologist internationally, plan for a master''s — fully funded scholarships at James Cook University (JCU, Australia''s top marine science school) and University of Auckland exist for Filipino students.', 'HONEST ASSESSMENT: BS Marine Biology is one of the most difficult degrees to convert to direct international employment. The pure research pathway almost universally requires a master''s or PhD. Internationally recognized Marine Biologist positions are very competitive globally — even PhD holders struggle to find permanent positions. The most realistic BS-level international paths are: (1) Dive industry — scientific diving instructor plus marine biology background equals employment at dive resorts, marine protected area management, or eco-tourism operators in Australia, Palau, Maldives, Indonesia, and Thailand. (2) Fisheries observer or fisheries management roles with international organizations (FAO, SEAFDEC, WCPFC). (3) Environmental consulting with marine component — EIA for offshore development. (4) Aquaculture technician roles internationally — growing sector with actual BS-level demand. The Philippines'' rich marine biodiversity gives Filipino marine biologists academic recognition, but converting this to employment abroad with just a BS is very challenging.')
