INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-012', 'BS Marine Science', 'Science & Math', 'DOMESTIC', 'Low', ARRAY['Australia', 'Norway', 'USA', 'Netherlands', 'Japan'], FALSE, NULL, 4, 'Specialize in physical oceanography or GIS and remote sensing — this opens offshore energy and coastal engineering consulting. Get certified in hydrographic surveying (FIG or IHO Category A or B) through online programs — this is a globally portable technical credential. DOST-PCAARRD and NAMRIA are worth joining early for domestic experience that supports later international opportunities.', 'HONEST ASSESSMENT: BS Marine Science (broader than Marine Biology, includes physical oceanography, marine geology, and chemical oceanography) has similar international career challenges as Marine Biology. Research roles require master''s or PhD. BS-level international opportunities are niche: (1) Offshore oil and gas environmental monitoring — marine scientists are hired by EPC contractors for environmental baseline studies and monitoring during drilling and production. This is actually accessible with a BS plus diving plus GIS skills. (2) Offshore wind farm environmental assessment — rapidly growing sector in Europe (Netherlands, Germany, UK, Denmark). (3) Port and coastal engineering support — hydrographic surveying, sediment analysis. (4) Aquaculture industry internationally. The main difference from Marine Biology: Marine Science graduates with strong physical oceanography and GIS skills can enter offshore energy sector environmental roles more easily than pure marine biologists.')
