INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-007', 'BS Medical Biology', 'Health Professions', 'INTERNATIONAL', 'Moderate', ARRAY['USA', 'UK', 'Germany', 'Canada', 'Australia'], FALSE, NULL, 4, 'Treat BS Medical Biology as a launch pad: either pursue MD (medicine) locally or abroad, or get an MS/PhD scholarship at a foreign university to enter biotech/pharma research.', 'BS Medical Biology is primarily a pre-med/research track in PH. No PRC board exam creates both challenge (no credential benchmark) and flexibility (careers in research, biotech, pharma, public health). International career paths are via: (1) graduate school (MS/PhD) in USA, UK, Germany, Australia; (2) research assistant/lab technician roles; (3) biotech/pharma industry jobs; (4) medical school (MD/MBBS) abroad. Direct OFW deployment is rare — this is an education-first, career-second path. USA and UK have the most developed biotech industries. Germany has strong pharmaceutical industry (Bayer, BASF, Merck KGaA).')
