INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-013', 'BS Meteorology', 'Science & Math', 'DOMESTIC', 'Low-Medium', ARRAY['USA', 'Australia', 'Canada', 'UK', 'UAE (oil and gas weather)'], FALSE, NULL, 4, 'Get ICAO aviation meteorologist certification — CAAP (Philippine) administers this. It is the most portable meteorology credential internationally. Offshore weather forecasting is a real and underappreciated niche — oil companies pay well for forecasters willing to work rotation schedules. DTN, Offshore Weather Services, and StormGeo all recruit from the Philippines. Learn Python for weather data analysis — NWP (Numerical Weather Prediction) modeling skills are increasingly required.', 'HONEST ASSESSMENT: BS Meteorology has a narrow international career pathway. Domestic employers (PAGASA, DOST, CAAP) absorb most Filipino meteorology graduates. International career paths exist but are limited: (1) Aviation meteorology — ICAO requires certified meteorologists at international airports. Openings in Middle East, Southeast Asia, and Africa. Philippine meteorologists with ICAO certifications have been deployed to Qatar and UAE. (2) Offshore or oil and gas weather forecasting — oil platforms and LNG ships require dedicated meteorologists. This is one of the most accessible BS-level international roles. Companies like Offshore Weather Services, DTN, and StormGeo hire from developing countries. (3) Private commercial weather services — IBM The Weather Company, Maxar Technologies, private forecasting companies. These are increasingly remote-capable. (4) WMO or UNDP technical assistance — international organizations deploy meteorologists to developing countries for capacity building. (5) Academic or research roles require master''s or PhD. Note: PAGASA is severely understaffed and holds on to its meteorologists tightly. Government scholars may have service obligations.')
