INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-004', 'BS Midwifery', 'Health Professions', 'INTERNATIONAL', 'Moderate', ARRAY['UK', 'Saudi Arabia', 'UAE', 'Australia', 'Ireland'], TRUE, 'Midwife Licensure Exam', 4, 'Target UK NHS direct recruitment for best pay and PR pathway; consider upskilling with BSN for wider Gulf options.', 'PH midwifery is a distinct BS degree (4 years) but most destination countries recognize it within a midwifery-nursing framework. UK (NMC) has a dedicated midwife register and actively recruits internationally. Gulf countries (Saudi, UAE) recruit under nursing-midwife classification. Australia (ANMAC) has strict midwifery standards and may require bridging. PH midwives often retrain as nurses (BSN) abroad to access wider job markets. Ireland has active midwifery shortage.')
