INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-014', 'BS Molecular Biology and Biotechnology (MBB)', 'Science & Math', 'INTERNATIONAL', 'Medium-High', ARRAY['USA', 'UK', 'Singapore', 'Ireland', 'Germany'], FALSE, NULL, 4, 'Target bioprocess technician and QC Analyst roles in Ireland — Amgen Dun Laoghaire, Janssen Biologics Cork, and MSD Carlow are all actively hiring BS-level biotech graduates internationally. The Critical Skills Employment Permit in Ireland has a clear PR pathway after 2 years. If you want to be a research scientist, plan for a master''s — look at NUS Singapore, Queen''s University Belfast, or UCL London for MBB-aligned master''s programs.', 'BS Molecular Biology and Biotechnology is one of the better positioned pure-science degrees for international employment because of two specific industry pipelines: (1) Ireland pharmaceutical and biotech manufacturing — Biologics production facilities (Amgen, Janssen, MSD, Regeneron, and Shire or Takeda all have large Irish biopharma plants) hire BS-level bioprocess technicians, QC analysts, and validation engineers directly. This is a genuine BS-level international pipeline. Ireland specifically hires Filipino biotechnology and science graduates for these roles via the Critical Skills Employment Permit. (2) Singapore Biopolis or biotech manufacturing — Lonza, Pfizer, and GSK all have significant manufacturing presence in Singapore hiring BS-level bioprocess and QC staff. (3) USA: Research associate or lab technician roles at biotech companies (not research scientist level — that is PhD). Production technician at pharmaceutical or biotech facilities. (4) Germany: Biotechnology technician in pharma production (Bayer, BASF, Merck KGaA) — requires B2 German for most positions. Graduate school: USA, UK, or Singapore master''s programs provide access to research scientist career track.')
