INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-004', 'BS Peace Studies', 'Social Sciences', 'DOMESTIC', 'Low', ARRAY['Philippines', 'Switzerland', 'Belgium', 'USA', 'Norway'], FALSE, NULL, 4, 'If Geneva, Brussels, or New York is the goal, a master''s degree is non-negotiable — apply to the Graduate Institute Geneva, Uppsala University (top peace research program), Notre Dame Kroc Institute, or George Mason''s Carter School for Peace and Conflict Resolution. Your Philippine Mindanao experience is genuinely valuable internationally — it is a complex, live peace process. Document it rigorously and present it as a case study, not just a job history.', 'BS Peace Studies is primarily designed for the Philippine context — specifically peacebuilding in Mindanao (Bangsamoro process, MILF/MNLF peace agreements) and community conflict resolution. The international career pathway in conflict resolution and peacebuilding is highly competitive and almost always requires a master''s degree. Realistic international pathways: (1) UN Department of Peace Operations (DPO) or political affairs officer roles — require P-2 entry via competitive YPP (Young Professionals Programme) exam or JPO sponsorship, plus master''s and multiple languages. (2) ICRC (International Committee of the Red Cross) — one of few organizations that will hire bachelor''s-level field staff for logistician/protection assistant roles; requires mobility (willingness to go to conflict zones) and competency in a second language. (3) Mindanao-focused work is internationally recognized — graduates who document peace process work with GPH-MILF, Bangsamoro Autonomous Region work, or Lumad protection can position themselves as Philippine peacebuilding specialists for international academic or policy conferences. (4) OCHA internships provide UN experience; UNIDIR (disarmament research) has internship programs. Honest assessment: Most Peace Studies graduates work in Mindanao NGOs, OPAPP, ARMM/BARMM, or LGU community conflict resolution. International career requires 7-10 years of specialized experience + master''s degree.')
