INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-008', 'BS Pharmacy', 'Health Professions', 'INTERNATIONAL', 'High', ARRAY['Canada', 'UK', 'Australia', 'Saudi Arabia', 'UAE'], TRUE, 'Pharmacist Licensure Exam', 5, 'Canada is fastest international route with highest pay; Gulf is fastest deployment with tax-free income.', 'Strong international pathway in all major English-speaking countries and Gulf. Canada PEBC now allows international graduates to skip Evaluating Exam (from May 2025) if eligible. UK requires OSPAP (1-year accredited course) then GPhC registration. Australia requires OPRA exams (written + OSCE) then AHPRA registration. Gulf (Saudi, UAE, Qatar, Kuwait) recruits directly with DataFlow + Prometric. Pharmacist demand rising globally due to aging populations and clinical pharmacy expansion.')
