INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-005', 'BS Psychology', 'Social Sciences', 'INTERNATIONAL', 'Moderate', ARRAY['UK', 'Australia', 'Singapore', 'Canada', 'UAE'], TRUE, 'Psychologist / Psychometrician Licensure Exam', 4, 'The PRC license is a great credential for the Philippines, but internationally it gets you ''assistant psychologist'' level at best. If you want to be a full psychologist internationally, plan for a master''s degree. The most internationally-portable short-term path: go into I/O psychology (HR, talent assessment, organizational behavior) in Singapore or Hong Kong MNCs, where a BS + experience is valued without clinical registration requirements. Alternatively, the UAE and Gulf have demand for school psychologists and HR assessment specialists at bachelor''s level.', 'Psychology has growing global demand due to the post-COVID mental health crisis. However, the pathway varies significantly by specialization and destination. KEY CHALLENGE: Most countries reserve the title ''Psychologist'' for doctoral-level practitioners. A BS Psychology + PRC license from PH is typically treated as an ''assistant psychologist'' or ''psychometric tester'' level internationally, NOT as a licensed clinical psychologist. CRITICAL DISTINCTION: (A) CLINICAL PSYCHOLOGY path — requires master''s/doctoral-level training (D.Psych UK, PsyD/PhD USA, master''s clinical AU) after the BS degree. Philippine BS + PRC license alone will NOT get HCPC or AHPRA clinical registration. (B) I/O PSYCHOLOGY path — Industrial-Organizational psychology in corporate HR, assessment centers, talent management is MORE internationally accessible at bachelor''s level + relevant experience, especially in Singapore, UAE, and HK. (C) PSYCHOMETRICS / ASSESSMENT path — psychometric assessment roles in schools, clinics, corporates are accessible with PRC license + experience. UK: HCPC regulates clinical, counselling, and forensic psychologists — requires postgraduate training. AU: AHPRA requires a minimum of 6 years training (4-year degree + 2-year master''s, or internship sequence). USA: ''psychologist'' requires doctoral degree in most states. MOST VIABLE INTERNATIONAL PATHWAY: (1) Pass PRC Psychologist exam. (2) Work 2-3 years in PH (HR/assessment, EAP, school psychology). (3) Apply to UK master''s in Applied Psychology or AU master''s in Professional Psychology. (4) Upon completion, register with HCPC/AHPRA and enter clinical workforce.')
