INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-010', 'BS Public Health', 'Health Professions', 'INTERNATIONAL', 'Moderate', ARRAY['USA', 'Canada', 'Australia', 'Singapore', 'UK'], FALSE, NULL, 4, 'Pursue an MPH (preferably at UP Manila or a US/AU/UK university) to unlock senior international roles; build experience in DOH or NGOs first.', 'No PRC board exam means no formal credential benchmark, but this also means international mobility is largely based on degree quality and experience. Entry-level international roles typically require MPH or equivalent. Strong demand in global health orgs (WHO, UNICEF, CDC, MSF), government health agencies, and NGOs. USA (CDC PHAP fellowship), Canada (PHAC), Australia (DoH) all hire public health professionals. Singapore MoH actively recruits for epidemiology and policy roles. Career ceiling is high with MPH + experience.')
