INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-011', 'BS Radiologic Technology', 'Health Professions', 'INTERNATIONAL', 'High', ARRAY['Saudi Arabia', 'UAE', 'USA', 'Australia', 'UK'], TRUE, 'Radiologic Technologist Licensure Exam', 4, 'Target Gulf for fastest deployment and tax-free income; pursue ARRT certification for the highest long-term earning potential in USA.', 'Strong OFW pathway. Gulf (Saudi, UAE, Qatar, Kuwait) has very high demand for radiographers/RadTechs under hospital expansion programs. ARRT (USA) is the gold standard credential — PH graduates can apply but must meet education equivalency. AHPRA registration in Australia requires degree equivalency + IELTS. UK requires HCPC registration via SCoR (Society of Radiographers) credentialing. Modality specialization (CT, MRI, Ultrasound, Nuclear Medicine) dramatically increases earning power.')
