INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('MID-006', 'BS Renewable Energy', 'Multi-Interdisciplinary', 'INTERNATIONAL', 'High', ARRAY['Australia', 'Germany', 'UK', 'Taiwan', 'USA'], FALSE, 'None (ECE/EE boards cover electrical engineering aspects separately; RE is a distinct multidisciplinary degree)', 4, 'NABCEP PV Associate certification ($375) is widely recognized in solar globally. For Australia, apply for Clean Energy Council accreditation — it is required to certify solar installations and creates direct employment. The IRA has made USA one of the best RE job markets in history — apply through companies like First Solar (thin-film), NextEra Energy (largest US renewable company), or Nextracker. Germany''s DAAD has specific fellowships for energy transition studies. Taiwan is actively recruiting offshore wind engineers with the government''s push to install 20GW offshore wind by 2035.', 'Renewable Energy is among the fastest-growing global employment sectors. IEA (International Energy Agency) estimates 30 million jobs in renewable energy globally by 2030, up from 13.7 million in 2023. The energy transition is a structural, decade-long megatrend creating sustained demand. Australian Clean Energy Council accreditation is relatively accessible for Filipino RE graduates and Australia has the fastest RE deployment per capita globally. Germany''s Energiewende (energy transition) has created the world''s largest renewable energy workforce with specific technical roles. Taiwan is a major market for offshore wind energy, with companies like Orsted, Vestas, and Jan De Nul operating offshore wind farms and recruiting engineers. USA''s Inflation Reduction Act (IRA) — $369B in clean energy spending — is the single largest driver of RE employment globally. Key specializations with highest demand: solar PV design/installation project management, offshore wind engineering, energy storage systems (battery), and grid integration. Philippines domestic opportunity: DOE RE Act (RA 9513) mandates 35% RE share by 2030, creating significant local demand through private energy developers (Solar Philippines, ACEN, Vena Energy, Total Energies Philippines).')
