INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-012', 'BS Respiratory Therapy', 'Health Professions', 'INTERNATIONAL', 'High', ARRAY['USA', 'Canada', 'Saudi Arabia', 'UAE', 'UK'], TRUE, 'Respiratory Therapist Licensure Exam', 4, 'USA offers highest salaries with strong demand; Gulf is fastest deployment option; pursue NBRC RRT for maximum US earning potential.', 'Respiratory therapy is a growing specialty globally, accelerated by COVID-19 increasing awareness. USA has the most structured path via NBRC (National Board for Respiratory Care) — CRT then RRT credentials. Canada has CSRT (Canadian Society of Respiratory Therapists) national exam. Gulf (Saudi, UAE, Qatar, Kuwait) has strong demand due to high prevalence of respiratory conditions (smoking, air quality). UK path via HCPC. BLS projects 12% job growth for RTs through 2034.')
