INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SOC-006', 'BS Social Work', 'Social Sciences', 'INTERNATIONAL', 'High', ARRAY['UK', 'Australia', 'Canada', 'New Zealand', 'Ireland'], TRUE, 'Social Worker Licensure Exam', 4, 'Pass the PRC Social Worker licensure exam immediately — this is your ticket internationally. The UK is the fastest deployment with a well-established route for Filipino social workers. Gain 2 years of post-licensure experience in child welfare, elder care, or mental health social work in the Philippines. Then apply to UK local authorities — Manchester, Leeds, Birmingham, and London boroughs actively post internationally. UK will often fund your adaptation period. The Health and Care Worker visa is available specifically for social workers. Ireland is an underrated option — similar language, EU access, very strong social work demand.', 'Social Work is one of the BEST international career options among social sciences courses. The UK is actively recruiting Filipino social workers to address a severe shortage in local authority children''s services, adult social care, and mental health social work. Key facts: (1) The Philippines is a recognized source country for UK social work — Social Work England accepts applications from internationally qualified social workers. (2) PRC Licensed Social Worker is the required base credential — you must have this before applying internationally. (3) UK process: Submit qualifications to Social Work England for international registration review; approximately 3-6 months processing; pass English language test; complete a period of supervised practice (adaptation period, typically 3-6 months). (4) Australia AASW: The Philippine social work qualification is generally assessed as meeting AASW membership requirements — this is well-established. Australia has significant shortages in child protection and NDIS disability support social work. (5) Canada: Provincial colleges (BCCSW, OCSWSSW etc.) assess international qualifications; varies by province; Ontario and BC most active recruitment. (6) New Zealand has a Social Workers Registration Board (SWRB) — international route available. (7) Ireland has Social Workers Registration Board Ireland (CORU) — also actively recruiting. SALARY: UK starting —28,000-35,000/year; senior practitioners —40,000-55,000. Australia AUD 65,000-95,000/year. Canada CAD 52,000-75,000. All significantly above Philippine rates.')
