INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('TEA-004', 'BS Special Needs Education (SPED)', 'Teacher Education', 'INTERNATIONAL', 'Very High', ARRAY['USA', 'UK', 'Australia', 'Canada', 'UAE'], TRUE, 'Licensure Exam for Teachers (LET) - Elementary/Secondary', 4, 'This is arguably the single best international teaching pathway from the Philippines. Apply to US school districts through Teach Away or US-based recruitment agencies. Many US public school districts in high-shortage states (Texas, Florida, California, Arizona) will sponsor your H-1B or J-1 visa. In the UK, SEND is on the Shortage Occupation List — faster visa and sometimes lower salary threshold. Australia has direct pathways through AITSL. Get experience with autism and multiple disabilities during your degree — these are the highest-demand specializations.', 'SPED teachers are among the most globally in-demand educators. In the USA, the Individuals with Disabilities Education Act (IDEA) mandates free appropriate public education for all children with disabilities — creating a structural, law-mandated shortage that cannot be filled domestically. The US Bureau of Labor Statistics consistently ranks Special Education as one of the most understaffed teaching fields, with 50,000+ unfilled positions annually. UK SEND (Special Educational Needs and Disability) teachers are on the official shortage occupation list, meaning faster visa processing. Australia''s NDIS (National Disability Insurance Scheme) created enormous demand for support workers and special education teachers. Canada''s inclusive education mandate across all provinces has the same structural driver as the US. Filipino SPED teachers are particularly competitive because Philippine SPED programs train graduates in autism spectrum disorder, intellectual disability, visual impairment, hearing impairment, and learning disabilities — comprehensive training that matches international needs.')
