INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-013', 'BS Speech and Language Pathology', 'Health Professions', 'INTERNATIONAL', 'High', ARRAY['USA', 'Canada', 'Australia', 'UK', 'UAE'], TRUE, 'SLP Licensure Exam', 4, 'USA offers the highest salary; consider completing a US MS-SLP program for ASHA CCC-SLP certification, or target Australia for fastest PR pathway.', 'SLP is one of the fastest-growing allied health professions globally. USA (ASHA CCC-SLP) is the premium destination with median salary of $95k-107k/year. Australia has strong demand and SPA provides clear registration pathway. Canada SAC certification + provincial licensing. UK HCPC registration. Gulf (UAE, Saudi Arabia) has rapidly growing demand especially in pediatric autism and dysphagia. Bachelor''s degree opens doors but Master''s (in USA, Canada) is standard entry for full ASHA certification. PH''s 4-year BS SLP is recognized in most countries.')
