INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('TEA-005', 'BS Sports and Exercise Science', 'Teacher Education', 'INTERNATIONAL', 'Moderate-High', ARRAY['UAE', 'Singapore', 'UK', 'Australia', 'Philippines'], FALSE, 'None (PE Teachers take PRC LET; Sports Science itself has no PRC board)', 4, 'Do NOT wait for a PRC board that doesn''t exist. Instead, invest in internationally recognized certifications: NSCA-CSCS ($435 exam fee) or ACSM-EP are global door-openers. For PE teaching internationally, if you took the LET track, that helps. In the UAE gym market, even an ACE Personal Trainer cert gets you jobs at Fitness First, GymNation, or Pure Gym. Professional sports is extremely competitive — start with academy coaching or school-based PE, build your portfolio, then move up.', 'Sports and Exercise Science has highly diverse career tracks with very different international profiles. Three main pathways: (1) PE Teacher in international schools — Gulf states, Singapore, Hong Kong, UK all hire PE specialists, this is the most accessible international pathway; (2) Strength & Conditioning Coach / Sports Performance — professional sports teams, elite academies, national sports programs; (3) Exercise Science / Fitness Industry — commercial gyms, corporate wellness, rehabilitation support. The PE teacher pathway is most accessible early-career. The professional sports pathway is very competitive but Philippines graduates have placed in Gulf football academies and Asian sports institutes. Notably: no PRC board exam for Sports Science itself — this means international certifications (NSCA, ACSM, ACE) are the de facto credentials. NSCA CSCS is the gold standard for S&C roles globally. Gulf fitness market (UAE, Saudi Arabia, Qatar) has boomed post-COVID with massive gym expansions.')
