INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('BUS-004', 'BS Tourism Management', 'Business & Management', 'INTERNATIONAL', 'Moderate', ARRAY['UAE', 'Singapore', 'UK', 'Australia', 'Spain'], FALSE, NULL, 4, 'Tourism Management gives you more career versatility than pure hospitality — you can go into policy, DMO work, airline operations, or international NGOs. The fastest cash path is still Gulf hotel/resort work. For the premium career track: IATA certification + 2 years experience = airline or airport management roles internationally. For ecotourism and development work: target ASEAN and international NGOs.', 'Tourism Management overlaps heavily with Hospitality Management for entry-level abroad roles. Key differentiators: destination marketing, tour operations, tourism policy, sustainable/ecotourism management. UN Tourism is headquartered in Madrid — salaries exempt from Spanish income tax. International tourism management salaries in USA average USD 103,000-133,500 (mid-to-senior level). Destination marketing managers earn USD 60,000-85,000. Tour guides in Italy/France/Japan earn EUR 20,000-33,000. ASEAN tourism sector is growing — Philippines and Indonesia are key markets. Heritage tourism and ecotourism roles growing globally. Cruise lines also recruit tourism graduates for shore excursions/travel desk roles.')
