INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-014', 'BS Veterinary Medicine (DVM/VMD)', 'Health Professions', 'INTERNATIONAL', 'High', ARRAY['Australia', 'New Zealand', 'UK', 'Canada', 'USA'], TRUE, 'Veterinarian Licensure Exam', 6, 'New Zealand and Australia offer the fastest path given the critical shortage — target large/mixed animal practice for maximum demand and incentive packages.', 'Veterinarian shortage is acute and global — Australia, NZ, UK, Canada, and USA all have active shortages. PH DVM is typically assessed by AVBC for AU/NZ. UK accepts via RCVS assessment and may require additional training period. Canada and USA require NAVLE (North American Veterinary Licensing Examination). New Zealand has vet on the Green List (critical shortage). Australia has TSS visa (482) actively used. Strong PR pathways in all major destinations. Large-animal vets are most needed; companion animal vets are more competitive in urban areas.')
