INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('SCI-015', 'BS Volcano and Seismology Related Fields', 'Science & Math', 'DOMESTIC', 'Very Low', ARRAY['USA', 'Japan', 'New Zealand', 'Italy', 'Indonesia'], FALSE, NULL, 4, 'Work at PHIVOLCS for 3-5 years first — this is your most valuable international asset. Publish if possible. Then apply for fully funded master''s programs at: University of Bristol (UK volcanic hazards), University of Auckland (geophysics), INGV (Italy — fully Italian government funded), or Tohoku University (Japan). UNDRR''s Sendai Framework implementation work needs disaster risk specialists — a pivot toward risk assessment and disaster risk reduction dramatically widens your international employment options.', 'HONEST ASSESSMENT: This is the most specialized and internationally restricted degree in this cluster. Global demand for volcanologists and seismologists is extremely limited — each country has only one or a handful of dedicated volcano or seismology agencies (USGS in USA, GNS Science in NZ, INGV in Italy, GSJ in Japan, GeoScience Australia), and competition for positions is fierce globally. PhD is the de facto requirement for any research position at these agencies. The few BS-level international paths are: (1) Geophysical field technician — seismic surveying for oil and gas exploration companies (SLB formerly Schlumberger, TGS, CGG Veritas). This is a real niche with deployment potential in Middle East, Africa, and Latin America. (2) Natural disaster risk consulting — multilateral organizations (World Bank, UNDP, UNDRR) employ disaster risk specialists; BS plus PHIVOLCS experience plus disaster risk certification is a viable pivot. (3) Earthquake engineering support roles for construction industry — adjacent to civil engineering seismic design. PHIVOLCS is understaffed and genuinely valued in ASEAN — some regional secondments exist under ASEAN SASOP (Standard Operating Procedure for Regional Standby Arrangements). The Philippines'' unique position as a highly active volcanic and seismic nation gives Filipino graduates specialized experience that is genuinely valued internationally, but the market is tiny.')
