INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('HLT-002', 'Doctor of Optometry', 'Health Professions', 'DOMESTIC', 'Low', ARRAY['Gulf (Kuwait', 'UAE)', 'Papua New Guinea', 'Palau', 'Singapore'], TRUE, 'Optometrist Licensure Exam', 6, 'If international practice is your goal, consider Gulf countries via DataFlow; for USA/Canada you effectively need to re-study.', 'Very limited OFW pathway. USA requires graduation from ACOE-accredited optometry school (US or Canada only) — PH OD degree not recognized. Canada requires International Optometry Bridging Program (IOBP). UK (GOC) considers PH OD if post-baccalaureate equivalent. Gulf countries (Kuwait, UAE, Saudi) accept OD with DataFlow + Prometric exam but volume is low. Most PH optometry graduates practice domestically. Papua New Guinea and Palau have small but open markets.')
