INSERT INTO career_courses (course_id, name, cluster, career_tag, demand, top_countries, board_exam, board_exam_name, duration_years, student_tip, ai_note)
VALUES ('OTH-009', 'Juris Doctor (JD) / Law', 'Other', 'DOMESTIC', 'Low', ARRAY['Philippines', 'UK', 'Singapore', 'USA', 'Australia'], TRUE, 'Philippine Bar Examination', 7, 'Pass the Philippine Bar — this is foundational. Then identify which international law track you want: (A) US track — work 2-3 years at a top Philippine law firm or corporate in-house, then apply for an LLM at NYU, Columbia, Georgetown, Michigan, or Fordham (all ABA-approved for NY Bar eligibility), take and pass the New York Bar, then apply at international law firms with NY offices or Philippines desks. (B) Singapore/Arbitration track — take the LLM at NUS or SMU Singapore (costs SGD 40,000-50,000; strong scholarship options), focus on international arbitration coursework, intern at SIAC, build an arbitration career. (C) UK/Global track — LLM at LSE, Oxford, Cambridge, then take the SQE to qualify as a solicitor. Most expensive but opens Magic Circle and global law firm doors. The NYC Bar route is the most financially rewarding long-term with US BigLaw starting salaries at $200,000+.', 'Critical reality: passing the Philippine Bar gives you the right to practice Philippine law — this does NOT entitle you to practice law in any other country. Every jurisdiction has its own bar/solicitor qualification. However, significant international law careers ARE available to Philippine-licensed lawyers via specific pathways: (1) LLM + FOREIGN BAR: An LLM from a reputable foreign law school, followed by the relevant bar exam, opens full international practice. Most strategic: New York State Bar (can be taken by foreign law graduates with an LLM from a NY-approved school — allows practice of US and NY law); New York has the most globally recognized US bar for international work. England/Wales: the SQE (Solicitors Qualifying Examination) replaced the old route in 2021; foreign lawyers with an LLM can take SQE and qualify as a solicitor. (2) INTERNATIONAL ARBITRATION: The most accessible international law career without a foreign bar. International arbitration (ICSID, ICC, SIAC, HKIAC, UNCITRAL) employs lawyers from any jurisdiction. Philippine lawyers with expertise in investment law, trade law, energy law, or construction can build international arbitration careers. Many operate as counsel or arbitrator for cross-border disputes involving Philippines. SIAC (Singapore International Arbitration Centre) and HKIAC are key Asia-Pacific hubs. (3) IN-HOUSE COUNSEL AT MNCs IN PH: MNCs (Procter & Gamble, Unilever, HSBC, Citibank, Accenture) operating in the Philippines need lawyers who understand Philippine law — these roles are domestic but internationally-connected, offering exposure to global legal work, higher pay ($40,000-80,000/year at senior levels), and pathways to international transfers within the MNC. (4) ADB / World Bank / ASEAN LEGAL ROLES: Asian Development Bank''s Office of the General Counsel employs Filipino lawyers. World Bank likewise. ASEAN Secretariat has a legal affairs department. These positions typically require an LLM and several years of litigation/transactional experience. (5) ACADEMIC ROUTE: Philippine law professors who publish in international journals and attend international academic conferences build a global academic law profile. (6) MIGRATION TO CANADA: Canada''s paralegal and legal consultant streams are accessible without full Canadian law qualification; Ontario specifically licenses paralegals. This is not full lawyer practice but an entry point.')
